def normalize_tags(tags):
    seen = set()
    result = []
    for tag in tags:
        key = tag.casefold()
        if key not in seen:
            seen.add(key)
            result.append(tag)
    return tuple(result)

def most_common_word(words):
    if not words:
        return None

    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1

    return max(counts, key=counts.get)

def intersection_labels(first, second):
    second_labels = set(second)
    seen = set()
    return tuple(
        label
        for label in first
        if label in second_labels and not (label in seen or seen.add(label))
    )

def common_suffix(words):
    if not words:
        return None

    suffix_length = 0
    for chars in zip(*(word[::-1] for word in words)):
        if len(set(chars)) != 1:
            break
        suffix_length += 1

    return words[0][-suffix_length:] if suffix_length else ""

def sort_events(events):
    from datetime import datetime, timezone

    def sort_key(event):
        time = datetime.fromisoformat(event["time"].replace("Z", "+00:00"))
        if time.tzinfo is None:
            time = time.replace(tzinfo=timezone.utc)
        return time.astimezone(timezone.utc)

    return sorted(events, key=sort_key)

def matrix_multiply(left, right):
    columns = list(zip(*right))
    return [[sum(a * b for a, b in zip(row, column)) for column in columns] for row in left]

def count_islands(grid):
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = set()
    count = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 1 or (r, c) in visited:
                continue

            count += 1
            visited.add((r, c))
            stack = [(r, c)]

            while stack:
                cr, cc = stack.pop()
                for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                    if (
                        0 <= nr < rows
                        and 0 <= nc < cols
                        and grid[nr][nc] == 1
                        and (nr, nc) not in visited
                    ):
                        visited.add((nr, nc))
                        stack.append((nr, nc))

    return count
